1	/**
2	 * HTTP surface of the budget chronology (Feature A) plus the create-envelope
3	 * type regression: GET /api/envelopes/versions, the version-carrying bodies of
4	 * POST /api/budget/edit and POST /api/envelopes/edit, and POST /api/envelopes
5	 * accepting every non-income envelope type the zod enum allows ("saving" was
6	 * live-rejected by a pre-remediation deploy; this pins the fixed behaviour).
7	 * Driven through the real app over the in-memory store, signed in, exactly as
8	 * the SPA calls it.
9	 */
10	
11	import { describe, test, expect } from "bun:test";
12	import type {
13	  BudgetVersionsResponse,
14	  CreateEnvelopeResponse,
15	  EditBudgetResponse,
16	  GridResponse,
17	} from "../src/server/contract.ts";
18	import { currentPeriod } from "../src/platform/time.ts";
19	import { monthBounds, nextPeriod, periodKey } from "../src/envelope/period.ts";
20	import { makeTestApp, postJson, getJson, LOCAL_USER_ID, type TestApp } from "./server-test-app.ts";
21	
22	const TZ = "Australia/Melbourne";
23	const NOW = currentPeriod(TZ);
24	const NEXT = nextPeriod(NOW);
25	const NEXT_FIRST = monthBounds(NEXT).first;
26	
27	async function createEnvelope(t: TestApp, cookie: string, body: unknown): Promise<string> {
28	  const res = await postJson(t.app, "/api/envelopes", body, cookie);
29	  expect(res.status).toBe(200);
30	  return ((await res.json()) as CreateEnvelopeResponse).id;
31	}
32	
33	async function grid(t: TestApp, cookie: string): Promise<GridResponse> {
34	  const res = await getJson(t.app, "/api/envelopes", cookie);
35	  expect(res.status).toBe(200);
36	  return (await res.json()) as GridResponse;
37	}
38	
39	describe("GET /api/envelopes/versions", () => {
40	  test("requires auth and an envelopeId", async () => {
41	    const t = await makeTestApp();
42	    expect((await getJson(t.app, "/api/envelopes/versions?envelopeId=x")).status).toBe(401);
43	    const cookie = await t.signIn();
44	    expect((await getJson(t.app, "/api/envelopes/versions", cookie)).status).toBe(400);
45	    expect((await getJson(t.app, "/api/envelopes/versions?envelopeId=nope", cookie)).status).toBe(404);
46	  });
47	
48	  test("a scheduled edit shows in the chronology with computed statuses", async () => {
49	    const t = await makeTestApp();
50	    const cookie = await t.signIn();
51	    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
52	
53	    // Schedule the change as of the first of NEXT month (the "1 Aug" case).
54	    const edit = await postJson(
55	      t.app,
56	      "/api/budget/edit",
57	      { lines: [{ envelopeId: id, amountCents: 60000 }], scope: "ongoing", effectiveFrom: NEXT_FIRST },
58	      cookie,
59	    );
60	    expect(edit.status).toBe(200);
61	    expect(((await edit.json()) as EditBudgetResponse).changed).toBe(1);
62	
63	    const res = await getJson(t.app, `/api/envelopes/versions?envelopeId=${id}`, cookie);
64	    expect(res.status).toBe(200);
65	    const body = (await res.json()) as BudgetVersionsResponse;
66	    expect(body.envelopeId).toBe(id);
67	    expect(body.versions.length).toBe(2);
68	    // Most recent first: the scheduled 600, then the completed-next-month 500.
69	    expect(body.versions[0]).toMatchObject({
70	      amountCents: 60000,
71	      effectiveFrom: NEXT_FIRST,
72	      effectiveTo: null,
73	      status: "scheduled",
74	    });
75	    expect(body.versions[1]?.amountCents).toBe(50000);
76	    expect(body.versions[1]?.status).toBe("active");
77	
78	    // The CURRENT month's grid still shows the old amount (scheduled = inert now).
79	    const g = await grid(t, cookie);
80	    expect(g.rows.find((r) => r.id === id)?.allocationCents).toBe(50000);
81	  });
82	
83	  test("an income budget change as of next month versions through the same mechanism", async () => {
84	    const t = await makeTestApp();
85	    const cookie = await t.signIn();
86	    const id = await createEnvelope(t, cookie, { name: "Salary", type: "income", parentId: null, budgetedCents: 500000, targetCents: 500000 });
87	
88	    const res = await postJson(
89	      t.app,
90	      "/api/envelopes/edit",
91	      { id, type: "income", budgetedCents: 600000, targetCents: 600000, effectiveFrom: NEXT_FIRST },
92	      cookie,
93	    );
94	    expect(res.status).toBe(200);
95	
96	    // This month's grid keeps the old income budget.
97	    const g = await grid(t, cookie);
98	    expect(g.income.find((i) => i.id === id)?.budgetedCents).toBe(500000);
99	
100	    // The chronology carries the bootstrapped baseline and the scheduled change.
101	    const versions = ((await (
102	      await getJson(t.app, `/api/envelopes/versions?envelopeId=${id}`, cookie)
103	    ).json()) as BudgetVersionsResponse).versions;
104	    expect(versions.length).toBe(2);
105	    expect(versions[0]).toMatchObject({ amountCents: 600000, status: "scheduled" });
106	    expect(versions[1]).toMatchObject({ amountCents: 500000, status: "active" });
107	
108	    // Next month's grid resolves to the new figure (query the month explicitly).
109	    const bounds = monthBounds(NEXT);
110	    const nextGrid = await getJson(t.app, `/api/envelopes?from=${bounds.first}&to=${bounds.last}`, cookie);
111	    expect(nextGrid.status).toBe(200);
112	    const ng = (await nextGrid.json()) as GridResponse;
113	    expect(ng.period).toBe(periodKey(NEXT));
114	    expect(ng.income.find((i) => i.id === id)?.budgetedCents).toBe(600000);
115	  });
116	
117	  test("completePrevious=false coexists and SUMS in the shared months", async () => {
118	    const t = await makeTestApp();
119	    const cookie = await t.signIn();
120	    const id = await createEnvelope(t, cookie, { name: "Groceries", type: "expense", budgetedCents: 50000, period: "monthly" });
121	
122	    const res = await postJson(
123	      t.app,
124	      "/api/budget/edit",
125	      {
126	        lines: [{ envelopeId: id, amountCents: 20000 }],
127	        scope: "ongoing",
128	        effectiveFrom: NEXT_FIRST,
129	        completePrevious: false,
130	      },
131	      cookie,
132	    );
133	    expect(res.status).toBe(200);
134	
135	    const bounds = monthBounds(NEXT);
136	    const nextGrid = (await (
137	      await getJson(t.app, `/api/envelopes?from=${bounds.first}&to=${bounds.last}`, cookie)
138	    ).json()) as GridResponse;
139	    expect(nextGrid.rows.find((r) => r.id === id)?.allocationCents).toBe(70000);
140	  });
141	
142	  test("a malformed effectiveFrom is a 400, not an engine exception", async () => {
143	    const t = await makeTestApp();
144	    const cookie = await t.signIn();
145	    const res = await postJson(
146	      t.app,
147	      "/api/budget/edit",
148	      { lines: [], scope: "ongoing", effectiveFrom: "August 1st" },
149	      cookie,
150	    );
151	    expect(res.status).toBe(400);
152	  });
153	});
154	
155	describe("POST /api/envelopes accepts every non-income envelope type (live regression)", () => {
156	  test("type 'saving' creates cleanly, keeps its type, and materialises its budget", async () => {
157	    const t = await makeTestApp();
158	    const cookie = await t.signIn();
159	    const res = await postJson(
160	      t.app,
161	      "/api/envelopes",
162	      { name: "Holiday Fund", type: "saving", budgetedCents: 30000, period: "monthly" },
163	      cookie,
164	    );
165	    expect(res.status).toBe(200);
166	    const created = (await res.json()) as CreateEnvelopeResponse;
167	    expect(created.type).toBe("saving");
168	
169	    const g = await grid(t, cookie);
170	    const row = g.rows.find((r) => r.id === created.id);
171	    expect(row?.type).toBe("saving");
172	    // The template line materialised into the current month.
173	    expect(row?.allocationCents).toBe(30000);
174	  });
175	
176	  test("types 'envelope' and 'working' create cleanly too", async () => {
177	    const t = await makeTestApp();
178	    const cookie = await t.signIn();
