async listUnmappedCategories(
  userId: UserId,
  opts: { from?: string; to?: string } = {},
): Promise<UnmappedCategory[]> {
  const dismissed = new Set(await this.store.listDismissedCategoryIds(userId));
  return (await this.aggregateUnmappedCategories(userId, opts)).filter(
    (c) => !dismissed.has(c.categoryId),
  );
}

/**
 * The DISMISSED complement of listUnmappedCategories: categories the user
 * cleared from the budget page's new-categories card. Same aggregates, so the
 * Settings "Not synced" section shows the identical figures. A dismissed
 * category that is later adopted gains a mapping and drops out of both lists
 * naturally (its transactions stop resolving to no envelope).
 */
async listDismissedCategories(userId: UserId): Promise<UnmappedCategory[]> {
  const dismissed = new Set(await this.store.listDismissedCategoryIds(userId));
  return (await this.aggregateUnmappedCategories(userId, {})).filter((c) =>
    dismissed.has(c.categoryId),
  );
}

