describe("category dismissal (clear / Not synced / restore)", () => {
  test("requires auth on both routes", async () => {
    const t = await makeTestApp();
    expect((await getJson(t.app, "/api/categories/dismissed")).status).toBe(401);
    expect((await postJson(t.app, "/api/categories/dismiss", { categoryId: "x", dismissed: true })).status).toBe(401);
  });

  test("a cleared category leaves unmapped, lists under dismissed, and restore reverses it", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    await t.store.upsertTransactions(LOCAL_USER_ID, [
      txRaw("g1", "cat-gym", "Gym", -1500, MID),
      txRaw("c1", "cat-coffee", "Coffee", -500, MID),
    ]);

    // Clear Gym: it disappears from unmapped (the budget page card)…
    const dismiss = await postJson(t.app, "/api/categories/dismiss", { categoryId: "cat-gym", dismissed: true }, cookie);
    expect(dismiss.status).toBe(200);
    const afterClear = await unmapped(t, cookie);
    expect(afterClear.categories.map((c) => c.categoryId)).toEqual(["cat-coffee"]);

    // …and appears under Settings → Not synced with the SAME aggregates.
    const dismissed = await getJson(t.app, "/api/categories/dismissed", cookie);
    expect(dismissed.status).toBe(200);
    const list = (await dismissed.json()) as { categories: { categoryId: string; transactionCount: number; totalCents: number }[] };
    expect(list.categories).toHaveLength(1);
    expect(list.categories[0]).toMatchObject({ categoryId: "cat-gym", transactionCount: 1, totalCents: -1500 });

    // Restore: back on the budget page, gone from Not synced.
    const restore = await postJson(t.app, "/api/categories/dismiss", { categoryId: "cat-gym", dismissed: false }, cookie);
    expect(restore.status).toBe(200);
    const afterRestore = await unmapped(t, cookie);
    expect(afterRestore.categories.map((c) => c.categoryId).sort()).toEqual(["cat-coffee", "cat-gym"]);
    const dismissedAfter = (await (await getJson(t.app, "/api/categories/dismissed", cookie)).json()) as { categories: unknown[] };
    expect(dismissedAfter.categories).toHaveLength(0);
  });

  test("adopting a dismissed category removes it from the Not synced list too", async () => {
    const t = await makeTestApp();
    const cookie = await t.signIn();
    await t.store.upsertTransactions(LOCAL_USER_ID, [txRaw("g1", "cat-gym", "Gym", -1500, MID)]);
    await postJson(t.app, "/api/categories/dismiss", { categoryId: "cat-gym", dismissed: true }, cookie);
    const adopt = await postJson(
      t.app,
      "/api/categories/adopt",
      { categoryId: "cat-gym", name: "Gym", type: "expense", budgetedCents: 5000, period: "monthly" },
      cookie,
    );
    expect(adopt.status).toBe(200);
    const dismissedAfter = (await (await getJson(t.app, "/api/categories/dismissed", cookie)).json()) as { categories: unknown[] };
    expect(dismissedAfter.categories).toHaveLength(0);
  });

  test("a malformed dismiss body is a 400", async () => {
