// Ongoing: version the change. Unchanged lines (the wizard posts every
// row) resolve to their current amount for the effective month and are
// skipped — UNLESS the request carries an explicit end date: "same
// amount until <date>" is a real schedule change (this is how a budget
// is ENDED without touching its amount), so it must not no-op.
const beforeCents = resolveAmountForMonth(lines, line.envelopeId, effMonth);
if (beforeCents === line.amountCents && req.effectiveTo === undefined) continue;

const prior = currentLineFor(lines, line.envelopeId, effMonth);
if (completePrevious) {
  const cutoff = previousDay(effectiveFrom);
  for (let i = 0; i < lines.length; i++) {
    const t = lines[i]!;
    if (t.envelopeId !== line.envelopeId) continue;
    // Truncate every version whose window reaches effectiveFrom — open
    // AND already-completed ones. A version closed at e.g. the 4th by an
