/**
 * Budget route handlers: the budget history feed (ISC-77) and the Edit Budget
 * wizard submit (ISC-72). Both run against the real budget engine and are scoped
 * to the authenticated user. Saving is never blocked; an imbalance only alerts.
 */

import { Hono } from "hono";
import type { Container } from "../../composition.ts";
import type { Services } from "../services.ts";
import type { EditBudgetRequest } from "../contract.ts";
import { currentPeriod, resolveSession, UNAUTHENTICATED } from "../http.ts";
import { parseBody, editBudgetSchema } from "../validate.ts";

export function registerBudget(api: Hono, container: Container, services: Services): void {
  api.get("/budget/history", async (c) => {
    const session = await resolveSession(c, container);
    if (!session) return c.json(UNAUTHENTICATED, 401);
    return c.json(await services.budget.getHistory(session.userId));
  });

  api.post("/budget/edit", async (c) => {
    const session = await resolveSession(c, container);
    if (!session) return c.json(UNAUTHENTICATED, 401);
    const parsed = await parseBody(c, editBudgetSchema);
    if (!parsed.ok) return parsed.response;
    // The schema is derived from (and validated against) EditBudgetRequest; the
    // cast bridges zod's `period?: T | undefined` to the contract's `period?: T`
    // under exactOptionalPropertyTypes.
    const req = parsed.value as EditBudgetRequest;
    return c.json(await services.budget.editBudget(session.userId, currentPeriod(container.config.timezone), req));
  });
}

