27	/**
28	 * Edit Budget wizard (ISC-72). The recurring template is edited here, not inline
29	 * on the grid. It now includes INCOME alongside spending, and groups every line
30	 * into the same four sections as the budget page (Income / Savings / Expenses /
31	 * Envelopes). Income lines edit the expected-income budget (the balancing figure)
32	 * via POST /api/envelopes/edit; spending lines edit the template via
33	 * POST /api/budget/edit, entered in a per-row period and normalised to a monthly
34	 * equivalent (ISC-94). Search, section/category filters, and sort scale the list.
35	 * The running zero-based check alerts (never blocks) when unbalanced (ISC-30/32).
36	 * Data is the real grid response; nothing is invented (ISC-83).
37	 */
38	type TypeFilter = "all" | "income" | "expense" | "saving" | "envelope";
39	type SortKey = "name" | "amount" | "category";
40	
41	interface Draft {
42	  amountCents: number; // entered in the row's selected period
43	  period: BudgetPeriod;
44	}
45	
46	/** The spending sections, rendered in budget-page order under their own headers. */
47	const SPENDING_SECTIONS: readonly { type: Exclude<EnvelopeType, "income">; title: string; icon: LucideIcon }[] = [
48	  { type: "saving", title: "Savings", icon: PiggyBank },
49	  { type: "expense", title: "Expenses", icon: Receipt },
50	  { type: "envelope", title: "Envelopes", icon: Mail },
51	];
52	
53	/**
54	 * The figure the wizard edits: the row's OWN allocation, never the rolled-up
55	 * descendant total. For a leaf own == rolled, so the fallback (older payloads
56	 * without the field) is exact there; for a parent the own line is the only
57	 * editable figure.
58	 */
59	const ownAlloc = (r: EnvelopeRow): number => r.ownAllocationCents ?? r.allocationCents;
60	
61	export function EditBudgetPage() {
62	  const navigate = useNavigate();
63	  const invalidateBudget = useInvalidateBudget();
64	  // Shared this-month grid query (deduped with the other this-month consumers).
65	  const { data: grid = null, isLoading: loading } = useEnvelopes({ period: "this-month" });
66	  const [draft, setDraft] = React.useState<Record<string, Draft>>({});
67	  const [incomeDraft, setIncomeDraft] = React.useState<Record<string, number>>({}); // monthly budget cents
68	  const [scope, setScope] = React.useState<ChangeScope>("ongoing");
69	  const [saved, setSaved] = React.useState(false);
70	  const [busy, setBusy] = React.useState(false);
71	  const [error, setError] = React.useState<string | null>(null);
72	
73	  // Budget chronology (Feature A): the effective window for CHANGED lines and
74	  // whether the previous version is completed. Default From = first of the
75	  // CURRENT month (matches today's edit semantics); the user moves it to a
76	  // future date to schedule a change (e.g. income change as of 1 Aug).
77	  const [effectiveFrom, setEffectiveFrom] = React.useState<string>(firstOfCurrentMonthIso());
78	  const [effectiveTo, setEffectiveTo] = React.useState<string>("");
79	  // A 409 scheduled_conflict from the guarded write path: the save would cover
80	  // a budget scheduled for a future date. Surfaced as a warning with an explicit
81	  // "replace scheduled budgets and save" retry (doctrine D3: never implicit).
82	  const [scheduledConflict, setScheduledConflict] = React.useState<string | null>(null);
83	  // Per-row expanded chronology (the History affordance).
84	  const [historyOpen, setHistoryOpen] = React.useState<Set<string>>(() => new Set());
85	  const toggleHistory = (id: string) =>
86	    setHistoryOpen((prev) => {
87	      const next = new Set(prev);
88	      if (next.has(id)) next.delete(id);
89	      else next.add(id);
90	      return next;
91	    });
92	
93	  // Toolbar state.
94	  const [search, setSearch] = React.useState("");
95	  const [typeFilter, setTypeFilter] = React.useState<TypeFilter>("all");
96	  const [categoryFilter, setCategoryFilter] = React.useState<string>("all");
97	  const [sortKey, setSortKey] = React.useState<SortKey>("category");
98	
99	  // Seed the editable drafts once from the first loaded grid. A later background
100	  // refetch (e.g. after a save invalidates the grid) must not clobber in-progress
101	  // edits, so seeding is guarded to run a single time.
102	  const seededRef = React.useRef(false);
103	  React.useEffect(() => {
104	    if (!grid || seededRef.current) return;
