/** Today (YYYY-MM-DD) in the configured budget timezone. */
private today(): string {
  return todayISO(this.tz, this.now());
}

private async event(
  userId: UserId,
  kind: string,
async listIncomeEnvelopes(userId: UserId): Promise<IncomeEnvelope[]> {
  const rows = this.db
    .query(
      `SELECT id, name, source, budgeted_cents, actual_cents, target_cents, capital_to_expense_cents
       FROM income_envelopes WHERE user_id = ?`,
    )
    .all(userId) as IncomeRow[];
  return rows.map((r) => ({
    id: r.id,
    userId,
    name: r.name,
    source: r.source,
    budgetedCents: r.budgeted_cents,
    actualCents: r.actual_cents,
    targetCents: r.target_cents,
  }));
}

async upsertIncomeEnvelope(userId: UserId, e: IncomeEnvelope): Promise<void> {
  this.db.run(
    `INSERT INTO income_envelopes
       (user_id, id, name, source, budgeted_cents, actual_cents, target_cents, capital_to_expense_cents)
     VALUES (?, ?, ?, ?, ?, ?, ?, ?)
     ON CONFLICT (user_id, id) DO UPDATE SET
       name = excluded.name,
       source = excluded.source,
       budgeted_cents = excluded.budgeted_cents,
       actual_cents = excluded.actual_cents,
       target_cents = excluded.target_cents,
       capital_to_expense_cents = excluded.capital_to_expense_cents`,
    [
      userId,
      e.id,
      e.name,
      e.source,
      e.budgetedCents,
      e.actualCents,
      e.targetCents ?? 0,
      0,
    ],
  );
}

