150	export class SqliteStore implements BudgetStore {
151	  private readonly db: Database;
152	  /** Set while a withTransaction is open, so nested calls join it (never re-BEGIN). */
153	  private readonly txContext = new AsyncLocalStorage<true>();
154	  /** Serialises top-level transactions on the single connection. */
155	  private txQueue: Promise<unknown> = Promise.resolve();
156	
157	  constructor(path: string) {
158	    this.db = new Database(path, { create: true });
159	    // Enforce referential integrity locally so tenant FKs actually bite.
160	    this.db.run("PRAGMA foreign_keys = ON");
161	    this.db.run("PRAGMA journal_mode = WAL");
162	  }
163	
164	  /**
165	   * All-or-nothing transaction (see the Store port for the full semantics).
166	   * bun:sqlite's db.transaction() is sync-only, so this hand-rolls
167	   * BEGIN IMMEDIATE / COMMIT / ROLLBACK around the async `fn`. Re-entrancy is
168	   * guarded via AsyncLocalStorage rather than a bare depth counter: a plain
169	   * counter cannot tell a nested call (inside `fn`, must join) from a
170	   * concurrent caller (must wait), and joining a stranger's transaction would
171	   * let its rollback silently eat committed-looking writes. Nested calls join;
172	   * concurrent top-level calls queue.
173	   */
174	  async withTransaction<T>(fn: () => Promise<T>): Promise<T> {
175	    if (this.txContext.getStore()) return fn(); // nested: join the outer transaction
176	
177	    const run = async (): Promise<T> => {
178	      this.db.run("BEGIN IMMEDIATE");
179	      try {
180	        const out = await this.txContext.run(true, fn);
181	        this.db.run("COMMIT");
182	        return out;
183	      } catch (err) {
184	        this.db.run("ROLLBACK");
185	        throw err;
186	      }
187	    };
188	    const result = this.txQueue.then(run, run);
189	    this.txQueue = result.catch(() => undefined); // keep the queue alive past failures
190	    return result;
191	  }
192	
193	  async migrate(): Promise<void> {
194	    const run = this.db.transaction(() => {
195	      for (const stmt of SCHEMA_SQL) this.db.run(stmt);
196	      // Backfill additive columns on tables that predate them. SQLite has no
197	      // ADD COLUMN IF NOT EXISTS, so guard each ALTER on PRAGMA table_info.
198	      for (const { table, column, ddl } of ADDITIVE_COLUMNS) {
199	        const cols = this.db.query(`PRAGMA table_info(${table})`).all() as { name: string }[];
200	        if (!cols.some((c) => c.name === column)) {
201	          this.db.run(`ALTER TABLE ${table} ADD COLUMN ${column} ${ddl}`);
202	        }
203	      }
204	      // Collapse duplicate (user_id, envelope_id, period) allocation rows, then
205	      // enforce uniqueness. The de-dup MUST precede the index or a dirty DB
206	      // could never migrate. Logged so a collapse is never silent.
207	      const dups = this.db.query(ALLOCATIONS_DEDUP_FIND_SQL).all() as {
208	        user_id: string;
209	        envelope_id: string;
210	        period: string;
211	        n: number;
212	      }[];
213	      if (dups.length > 0) {
214	        for (const d of dups) {
215	          console.log(
216	            `[migrate] collapsing ${d.n} duplicate allocation rows for user=${d.user_id} envelope=${d.envelope_id} period=${d.period} (keeping lowest id, summing amounts)`,
217	          );
218	        }
219	        for (const stmt of ALLOCATIONS_DEDUP_SQL) this.db.run(stmt);
220	      }
221	      this.db.run(ALLOCATIONS_UNIQUE_INDEX_SQL);
222	      // Garbage-era purge (see schema.ts): remove out-of-era allocations and
223	      // the mechanical sync-roll history they generated. Logged, idempotent.
224	      const garbage = this.db.query(GARBAGE_ALLOCATIONS_COUNT_SQL).get() as { n: number };
225	      if (garbage.n > 0) {
226	        console.log(`[migrate] purging ${garbage.n} out-of-era allocation rows (garbage-date materialisation)`);
227	        for (const stmt of GARBAGE_PURGE_SQL) this.db.run(stmt);
228	      }
229	    });
230	    run();
231	    // Reclaim the purged space. VACUUM cannot run inside a transaction; a
232	    // no-purge run makes this a fast no-op.
233	    this.db.run("VACUUM");
234	  }
235	
