237	   * Ensure a tenant row exists. Public beyond the Store interface so test
238	   * harnesses and the composition root can seed users (local seeds exactly one).
239	   */
240	  async ensureUser(userId: UserId, email?: string): Promise<void> {
241	    this.db.run(
242	      `INSERT INTO users (id, email, created_at, status)
243	       VALUES (?, ?, ?, 'active')
244	       ON CONFLICT (id) DO NOTHING`,

